// Build the page list for one company. Nothing is fetched here.
//
// Different pages from WF-02 on purpose. WF-02 is looking for evidence of
// engineering work; this is looking for who to write to, and those live on
// different pages. /team and /contact are the two that matter and neither is in
// the research list.

const PATHS = [
  '/contact', '/contact-us', '/kontakt',
  '/team', '/our-team', '/about', '/about-us', '/company',
  '/people', '/leadership', '/management',
  '/careers', '/jobs',
  '',
];
const USER_AGENT = 'AiSalesMachineBot/1.0 (+https://github.com/urosorolicki/ai-sales)';

return $input.all().map((item) => {
  const c = item.json;
  const site = typeof c.website === 'string' && /^https?:\/\//i.test(c.website)
    ? c.website.replace(/\/+$/, '')
    : 'https://' + c.domain;

  return {
    json: {
      ...c,
      base_url: site,
      robots_url: site + '/robots.txt',
      candidate_urls: PATHS.map((p) => site + p),
      user_agent: USER_AGENT,
    },
  };
});

// Apply robots.txt before fetching anything.
//
// This is a copy of the same node in WF-02, with the upstream node renamed.
// n8n has no way to share a function between workflows short of a sub-workflow
// call, and a sub-workflow for sixty lines of parsing would cost more than it
// saves. IF YOU CHANGE THE PARSING HERE, CHANGE IT IN WF-02 TOO - the whole
// point of honouring robots.txt is that it is honoured everywhere.
//
function parseRobots(text, agent) {
  const groups = [];
  let current = null;
  for (const rawLine of String(text).split(/\r?\n/)) {
    const line = rawLine.replace(/#.*$/, '').trim();
    if (!line) continue;
    const idx = line.indexOf(':');
    if (idx === -1) continue;
    const field = line.slice(0, idx).trim().toLowerCase();
    const value = line.slice(idx + 1).trim();

    if (field === 'user-agent') {
      if (!current || current.rules.length) {
        current = { agents: [], rules: [] };
        groups.push(current);
      }
      current.agents.push(value.toLowerCase());
    } else if ((field === 'allow' || field === 'disallow') && current) {
      current.rules.push({ allow: field === 'allow', path: value });
    }
  }

  const token = agent.split('/')[0].toLowerCase();
  const exact = groups.find((g) => g.agents.includes(token));
  const wildcard = groups.find((g) => g.agents.includes('*'));
  return (exact || wildcard || { rules: [] }).rules;
}

function isAllowed(path, rules) {
  let best = null;
  for (const rule of rules) {
    // An empty Disallow means "allow everything" and matches nothing.
    if (rule.path === '') continue;
    const pattern = rule.path.replace(/\*+$/, '');
    if (!path.startsWith(pattern)) continue;
    if (best === null || pattern.length > best.length) {
      best = { length: pattern.length, allow: rule.allow };
    }
  }
  return best === null ? true : best.allow;
}

const companies = $('Contact URLs').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const company = companies[i].json;
  const res = $input.all()[i].json ?? {};

  // neverError is on, so a 404 arrives as data, not as an exception. Either way
  // an unreadable robots.txt means no restrictions were published.
  const body = typeof res.data === 'string' ? res.data : '';
  const rules = body ? parseRobots(body, company.user_agent) : [];

  const allowed = [];
  const blocked = [];
  for (const url of company.candidate_urls) {
    const path = url.slice(company.base_url.length) || '/';
    (isAllowed(path, rules) ? allowed : blocked).push(url);
  }

  out.push({
    json: {
      ...company,
      urls: allowed,
      robots_blocked: blocked,
      robots_rules_found: rules.length,
    },
  });
}

return out;

// One item per fetched page arrives here. Group them back per company.
//
// The difference from WF-02's version of this node is what it keeps. WF-02
// strips tags to plain text, which throws away every mailto: link on the page -
// and a mailto: href is the single most reliable published address there is,
// because a human put it there to be clicked. They are pulled out of the raw
// HTML before anything is stripped.

const MAX_CHARS_PER_PAGE = 5000;
const MAX_CHARS_TOTAL = 20000;
const MAX_EMAILS = 40;

// Deliberately narrow. A greedy pattern matches version strings, image hashes
// and CSS selectors, and every false positive becomes something the verifier
// has to reject later.
const GH_LINK = /github\.com\/([A-Za-z0-9][A-Za-z0-9-]{0,38})(?![A-Za-z0-9-])/gi;

// Paths under github.com that are GitHub's own, not a company account.
const GH_RESERVED = new Set([
  'features', 'about', 'pricing', 'enterprise', 'login', 'join', 'marketplace',
  'explore', 'topics', 'collections', 'events', 'sponsors', 'readme', 'orgs',
  'apps', 'settings', 'site', 'security', 'customer-stories', 'trending',
  'search', 'new', 'notifications', 'issues', 'pulls', 'codespaces', 'sitemap',
]);

// Addresses and names that belong to machinery rather than to a person.

function harvestGithubLinks(html) {
  const out = [];
  GH_LINK.lastIndex = 0;
  let m;
  while ((m = GH_LINK.exec(String(html))) !== null) {
    const slug = m[1];
    if (GH_RESERVED.has(slug.toLowerCase())) continue;
    if (!out.includes(slug)) out.push(slug);
    if (out.length > 8) break;
  }
  return out;
}

const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;

function htmlToText(html) {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|li|h[1-6]|tr|section|article|td)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

// Some sites write addresses as "name (at) example.com" to defeat scrapers.
// Undoing that is reading what the page says, not defeating anything: the
// address is published, and the obfuscation is aimed at bulk harvesters.
function deobfuscate(text) {
  return String(text)
    .replace(/\s*\(\s*at\s*\)\s*/gi, '@')
    .replace(/\s*\[\s*at\s*\]\s*/gi, '@')
    .replace(/\s+at\s+([A-Za-z0-9.-]+)\s+dot\s+([A-Za-z]{2,})/gi, '@$1.$2')
    .replace(/\s*\(\s*dot\s*\)\s*/gi, '.')
    .replace(/\s*\[\s*dot\s*\]\s*/gi, '.');
}

const pages = $input.all();
const context = $('Split URLs').all();
const byCompany = new Map();

for (let i = 0; i < pages.length; i++) {
  const j = { ...context[i].json, ...(pages[i].json ?? {}) };
  const key = j.company_id;
  if (!key) continue;

  if (!byCompany.has(key)) {
    byCompany.set(key, {
      agent_run_id: j.agent_run_id,
      company_id: j.company_id,
      name: j.name,
      domain: j.domain,
      base_url: j.base_url,
      robots_blocked: j.robots_blocked ?? [],
      sources: [],
      github_hints: [],
      fetch_failures: [],
      sections: [],
      emails: [],
    });
  }
  const bucket = byCompany.get(key);

  const res = pages[i].json ?? {};
  const failed = res.error !== undefined || typeof res.data !== 'string' || res.data === '';
  if (failed) {
    const reason = res.error
      ? (typeof res.error === 'string' ? res.error : (res.error.message ?? 'request failed'))
      : 'empty response';
    bucket.fetch_failures.push(j.url + ' (' + reason + ')');
    continue;
  }

  const html = res.data;

  // mailto: first, off the raw HTML, before the tags are gone.
  for (const m of html.matchAll(/mailto:([^"'?\s>]+)/gi)) {
    const address = decodeURIComponent(m[1]).trim().toLowerCase();
    if (EMAIL_RE.test(address)) {
      EMAIL_RE.lastIndex = 0;
      bucket.emails.push({ email: address, source: j.url, from: 'mailto' });
    }
    EMAIL_RE.lastIndex = 0;
  }

  const text = deobfuscate(htmlToText(html));
  for (const m of text.matchAll(EMAIL_RE)) {
    bucket.emails.push({ email: m[0].trim().toLowerCase(), source: j.url, from: 'text' });
  }

  if (text.length < 40) {
    bucket.fetch_failures.push(j.url + ' (no usable text)');
    continue;
  }

  // Off the raw markup: htmlToText drops the href, and the account name is in
  // the href.
  for (const slug of harvestGithubLinks(res.data)) {
    if (!bucket.github_hints.includes(slug)) bucket.github_hints.push(slug);
  }

  bucket.sources.push(j.url);
  bucket.sections.push('### SOURCE: ' + j.url + '\n' + text.slice(0, MAX_CHARS_PER_PAGE));
}

const out = [];
for (const bucket of byCompany.values()) {
  let material = bucket.sections.join('\n\n');
  let truncated = false;
  if (material.length > MAX_CHARS_TOTAL) {
    material = material.slice(0, MAX_CHARS_TOTAL);
    truncated = true;
  }

  // Deduplicate, keeping the first sighting of each address so its source is
  // the page it was actually read from.
  const seen = new Set();
  const emails = [];
  for (const e of bucket.emails) {
    if (seen.has(e.email)) continue;
    seen.add(e.email);
    emails.push(e);
    if (emails.length >= MAX_EMAILS) break;
  }

  const { sections, emails: _raw, ...rest } = bucket;  // github_hints rides along in rest
  out.push({
    json: {
      ...rest,
      material,
      material_chars: material.length,
      material_truncated: truncated,
      pages_fetched: bucket.sources.length,
      // The verifier checks model output against this, so it has to carry the
      // addresses found in the raw HTML as well as the stripped text.
      harvested_emails: emails,
      // Truncation matters here: an address past the cut is not in the material
      // the model saw, and the verifier would reject it as invented.
      verification_haystack: (material + '\n' + emails.map((e) => e.email).join('\n')).toLowerCase(),
    },
  });
}

return out;

// Assemble the enrichment request. The prompt comes from prompts/enrichment.md
// and the output contract from agents/enrichment/schema.json, both read from
// disk, so neither is restated here and neither can drift from this node.

const MODEL = $env.OLLAMA_ENRICHMENT_MODEL || $env.OLLAMA_MODEL || 'llama3.1:8b';

function extractSystemPrompt(markdown) {
  const section = markdown.split(/^##\s+System prompt\s*$/m)[1];
  if (!section) throw new Error('prompts/enrichment.md: no "## System prompt" heading found');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/enrichment.md: no fenced block under "## System prompt"');
  const text = fence[1].trim();
  if (text.length < 200) throw new Error('prompts/enrichment.md: system prompt looks truncated');
  return text;
}

// Everything after the system prompt is the working guidance: who to return,
// what to do with titles, what "verbatim" means. The model needs it.
function extractGuidance(markdown) {
  const start = markdown.indexOf('## Who to return');
  if (start === -1) throw new Error('prompts/enrichment.md: no "## Who to return" section');
  return markdown.slice(start).trim();
}

const doc = $('Prompt To Text').first().json.data;
const systemPrompt = extractSystemPrompt(doc) + '\n\n' + extractGuidance(doc);

const schema = JSON.parse($('Schema To Text').first().json.data);
delete schema.$schema;
delete schema.$id;
delete schema.title;

return $input.all().map((item) => {
  const c = item.json;

  const lines = [
    'COMPANY',
    'Name: ' + c.name,
    'Domain: ' + c.domain,
    '',
    'ADDRESSES ALREADY FOUND IN THE MARKUP',
    c.harvested_emails.length
      ? c.harvested_emails.map((e) => '- ' + e.email + '  (' + e.source + ')').join('\n')
      : 'none',
    '',
    'PAGES',
    c.material || '(no readable text was fetched)',
    '',
    'Return the people and the role addresses you can read above.',
    'An empty result is a normal answer.',
  ];

  return {
    json: {
      agent_run_id: c.agent_run_id,
      company_id: c.company_id,
      name: c.name,
      domain: c.domain,
      model: MODEL,
      llm_request: {
        model: MODEL,
        temperature: 0,
        max_tokens: 3000,
        // Transcription, not reasoning. See docs/ollama.md for why this has to
        // be "none" and not "low".
        reasoning_effort: 'none',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: lines.join('\n') },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'enrichment', strict: true, schema },
        },
      },
    },
  };
});

// Verify everything the model said against the pages it was given.
//
// docs/architecture.md: the rules that matter are enforced, not requested. The
// prompt asks the model to transcribe rather than invent; this node is what
// makes that true. Nothing here trusts a single field of the response.
//
// The stakes are not abstract. An address that nobody published goes to a real
// person at a real company, and the first anyone hears of it is a bounce, a
// spam complaint, or a reply asking who we are and where we got their details -
// which under GDPR is a question with a required answer (docs/security.md).

const ROLE_LOCALPARTS = new Set([
  'info', 'hello', 'contact', 'kontakt', 'office', 'mail', 'email', 'enquiries',
  'inquiries', 'jobs', 'careers', 'career', 'recruiting', 'recruitment', 'hr',
  'posao', 'sales', 'support', 'help', 'admin', 'press', 'media', 'marketing',
  'billing', 'invoice', 'accounts', 'finance', 'legal', 'privacy', 'security',
  'abuse', 'postmaster', 'webmaster', 'noreply', 'no-reply', 'donotreply',
  'newsletter', 'team', 'partners', 'business', 'general',
]);

const EMAIL_SHAPE = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/;

const SENIORITY = [
  [/\b(ceo|chief\s|cto|cio|ciso|coo|cfo|founder|co-founder|owner|managing director)\b/i, 'c_level'],
  [/\b(vp|vice president)\b/i, 'vp'],
  [/\bhead of\b/i, 'head'],
  [/\bdirector\b/i, 'director'],
  [/\b(manager|lead engineer|engineering manager)\b/i, 'manager'],
  [/\b(lead|principal|staff)\b/i, 'lead'],
  [/\bsenior\b/i, 'senior'],
];

// Fold a name to the letters an email address would use: strip diacritics, drop
// everything that is not a letter. NFD handles c-caron and friends; d-stroke and
// eszett do not decompose and have to be listed.
function fold(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'd')
    .replace(/ß/g, 'ss')
    .replace(/ø/g, 'o')
    .replace(/ł/g, 'l')
    .replace(/æ/g, 'ae')
    .toLowerCase()
    .replace(/[^a-z]/g, '');
}

// Ordered most specific first. A single observed address can match more than
// one of these; the first match wins, so "first" and "last" alone sit at the
// bottom where they cannot steal a match from a two-part pattern.
// Words that make a label a group rather than a person. Smartly.io's site
// lists "Agency Teams", "Brand Teams" and "Creative Teams"; each passed every
// check - two words, present on the page - and the pattern inference then
// produced agency.teams@, brand.teams@ and three more addresses that almost
// certainly do not exist. docs/security.md forbids writing a role address as a
// person, but the role check only knows local-parts like "info" and "hello",
// and it never sees a name.
const COLLECTIVE = new RegExp('(^|\\s)(' + [
  'team', 'teams', 'group', 'groups', 'department', 'dept', 'division',
  'desk', 'office', 'crew', 'squad', 'staff', 'people', 'personnel',
  'support', 'sales', 'marketing', 'recruiting', 'recruitment', 'careers',
  'hr', 'admin', 'administration', 'services', 'partners', 'community',
  'everyone', 'all', 'us', 'we',
].join('|') + ')(\\s|$)', 'i');

// A person has a given name and a family name. Anything with a company suffix
// in it is an entity, not somebody to write to.
const ENTITY_SUFFIX = /(^|\s)(inc|llc|ltd|limited|gmbh|bv|b\.v|oy|ab|as|sa|srl|plc|corp|corporation|company|co)\.?(\s|$)/i;

function looksLikePerson(fullName, title) {
  if (COLLECTIVE.test(fullName)) return 'reads as a group, not a person';
  if (ENTITY_SUFFIX.test(fullName)) return 'reads as a company, not a person';
  // "Smartly Team" arrived with the title "Team": when the title is just the
  // name again, nothing on the page actually identified a person.
  if (title && fullName.toLowerCase().includes(String(title).toLowerCase()) &&
      String(title).trim().split(/\s+/).length < 3) {
    return 'its title is part of its own name, so no person was identified';
  }
  return null;
}

const PATTERNS = [
  { id: 'first.last', build: (f, l) => (f && l ? f + '.' + l : null) },
  { id: 'f.last',     build: (f, l) => (f && l ? f[0] + '.' + l : null) },
  { id: 'first_last', build: (f, l) => (f && l ? f + '_' + l : null) },
  { id: 'first-last', build: (f, l) => (f && l ? f + '-' + l : null) },
  { id: 'firstlast',  build: (f, l) => (f && l ? f + l : null) },
  { id: 'flast',      build: (f, l) => (f && l ? f[0] + l : null) },
  { id: 'last.first', build: (f, l) => (f && l ? l + '.' + f : null) },
  { id: 'lastf',      build: (f, l) => (f && l ? l + f[0] : null) },
  { id: 'first',      build: (f) => f || null },
  { id: 'last',       build: (f, l) => l || null },
];

function nameParts(fullName) {
  const parts = String(fullName || '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { first: '', last: '' };
  return { first: fold(parts[0]), last: fold(parts[parts.length - 1]) };
}

function seniorityFromTitle(title) {
  for (const [re, value] of SENIORITY) if (re.test(String(title || ''))) return value;
  return 'unknown';
}

const claims = $('Claim Companies').all();
const material = $('Merge GitHub Contacts').all();
const requests = $('Build Enrichment Request').all();
const responses = $input.all();

const out = [];

for (let i = 0; i < responses.length; i++) {
  const req = requests[i].json;
  const mat = material[i].json;
  const res = responses[i].json ?? {};

  const errors = [];
  const notes = [];
  const dropped = [];
  let parsed = null;
  let raw = '';
  let usage = null;

  // ---- the response itself -------------------------------------------------
  if (res.error !== undefined) {
    const e = res.error;
    errors.push('Enrichment model request failed: ' +
      (typeof e === 'string' ? e : (e && e.message) || JSON.stringify(e)));
  } else {
    usage = res.usage ?? null;
    const choice = Array.isArray(res.choices) ? res.choices[0] : null;
    if (!choice) {
      errors.push('Response contained no choices');
    } else if (choice.finish_reason === 'length') {
      errors.push('Response hit the token limit and is truncated. Use a model with a ' +
        'larger context window (OLLAMA_ENRICHMENT_MODEL)');
    } else {
      raw = (choice.message && choice.message.content) || '';
      if (!raw.trim()) errors.push('Model returned no text content');
      else {
        try { parsed = JSON.parse(raw); } catch (e) {
          errors.push('Response is not valid JSON: ' + e.message);
        }
      }
    }
  }
  if (parsed !== null && (typeof parsed !== 'object' || Array.isArray(parsed))) {
    errors.push('Response is valid JSON but not a JSON object');
    parsed = null;
  }

  if (errors.length) {
    out.push({ json: {
      agent_run_id: req.agent_run_id, company_id: req.company_id,
      name: req.name, domain: req.domain,
      valid: false, has_people: false, run_status: 'error',
      errors, error_message: errors.join('; '), notes: [], people: [], role_addresses: [],
      dropped: [], pattern: null, raw_response: raw, model_output: parsed, usage,
    } });
    continue;
  }

  const haystack = String(mat.verification_haystack || '');
  const domain = String(req.domain || '').toLowerCase();
  const harvested = new Map((mat.harvested_emails || []).map((e) => [e.email, e.source]));

  const onCompanyDomain = (email) => {
    const at = email.lastIndexOf('@');
    if (at === -1) return false;
    const host = email.slice(at + 1);
    return host === domain || host.endsWith('.' + domain);
  };
  const isRole = (email) => ROLE_LOCALPARTS.has(email.slice(0, email.indexOf('@')));

  // An address is only accepted if the pages actually contain it. The harvest
  // is the stronger check - it came out of the markup - but the haystack covers
  // an address the harvester's pattern missed.
  // A local model asked for a nullable field often answers with the string
  // "null" rather than JSON null. Treating that as a rejected address filled
  // the audit trail with drops for people who simply had no address, which
  // makes the real drops - the invented ones - harder to see.
  const ABSENT = new Set(['', 'null', 'none', 'n/a', 'na', 'unknown', 'undefined', '-']);

  function acceptEmail(candidate, who) {
    if (!candidate) return null;
    const email = String(candidate).trim().toLowerCase();
    if (ABSENT.has(email)) return null;
    if (!EMAIL_SHAPE.test(email)) { dropped.push(who + ': "' + candidate + '" is not an address'); return null; }
    if (!harvested.has(email) && !haystack.includes(email)) {
      dropped.push(who + ': address "' + email + '" does not appear on any fetched page');
      return null;
    }
    if (!onCompanyDomain(email)) {
      dropped.push(who + ': address "' + email + '" is not on ' + domain);
      return null;
    }
    return email;
  }

  // ---- people --------------------------------------------------------------
  const rawPeople = Array.isArray(parsed.people) ? parsed.people : [];
  const people = [];
  const usedEmails = new Set();
  // people carries a unique index on (company_id, lower(btrim(full_name))), and
  // Write People inserts every row in one statement. Two rows with the same
  // name abort the whole statement with "ON CONFLICT DO UPDATE command cannot
  // affect row a second time", so the company loses its entire enrichment run
  // over one repeated name. The model does repeat names - it reads the same
  // person off two pages - and only addresses were being deduplicated.
  const usedNames = new Set();
  const nameKey = (s) => String(s).trim().replace(/\s+/g, ' ').toLowerCase();

  for (const p of rawPeople) {
    const fullName = String(p.full_name || '').trim().replace(/\s+/g, ' ');
    if (fullName.length < 3 || !/\s/.test(fullName)) {
      dropped.push('person "' + fullName + '": not a full name');
      continue;
    }
    // An invented person cannot survive this. Whitespace is normalised on both
    // sides because a name can be split across markup.
    const foldedName = fullName.toLowerCase();
    const firstWord = foldedName.split(' ')[0];
    const lastWord = foldedName.split(' ').pop();
    if (!haystack.includes(foldedName) && !(haystack.includes(firstWord) && haystack.includes(lastWord))) {
      dropped.push('person "' + fullName + '": name does not appear on any fetched page');
      continue;
    }

    if (usedNames.has(nameKey(fullName))) {
      dropped.push('person "' + fullName + '": already listed on another page');
      continue;
    }

    const notPerson = looksLikePerson(fullName, p.title);
    if (notPerson) {
      dropped.push('person "' + fullName + '": ' + notPerson);
      continue;
    }

    let title = p.title === null || p.title === undefined ? null : String(p.title).trim();
    if (title && !haystack.includes(title.toLowerCase())) {
      notes.push('title "' + title + '" for ' + fullName + ' is not on the page; dropped');
      title = null;
    }

    let email = acceptEmail(p.email, 'person "' + fullName + '"');
    if (email && isRole(email)) {
      dropped.push('person "' + fullName + '": ' + email + ' is a role address, not a person');
      email = null;
    }
    if (email && usedEmails.has(email)) {
      dropped.push('person "' + fullName + '": ' + email + ' was already claimed by another person');
      email = null;
    }
    if (email) usedEmails.add(email);

    usedNames.add(nameKey(fullName));
    const parts = fullName.split(' ');
    people.push({
      full_name: fullName,
      first_name: parts[0],
      last_name: parts.length > 1 ? parts[parts.length - 1] : null,
      title,
      seniority: seniorityFromTitle(title),
      email,
      email_status: email ? 'valid' : 'unknown',
      linkedin_url: typeof p.linkedin_url === 'string' && /^https?:\/\/(www\.)?linkedin\.com\//i.test(p.linkedin_url)
        ? p.linkedin_url : null,
      source_url: email ? (harvested.get(email) || String(p.source || '')) : String(p.source || ''),
      discovery_method: email ? 'published_page' : null,
    });
  }

  // ---- contacts observed in the company's own repositories ----------------
  // Not model output, so not verified against the pages: each pair is a name
  // and an address that git recorded together in a commit on this company's
  // own repository. That is the observation docs/security.md requires before
  // any address may be derived, and the website never provides it - eleven
  // companies of this profile were checked and none published one.
  //
  // These are appended rather than merged over the model's people: a person the
  // model already found keeps the title it read off the page.
  for (const g of (Array.isArray(mat.github_people) ? mat.github_people : [])) {
    const email = String(g.email || '').toLowerCase();
    const fullName = String(g.full_name || '').trim();
    if (!email || !fullName) continue;
    if (usedEmails.has(email)) continue;
    if (isRole(email)) continue;
    // The unique index is on (company_id, lower(trim(full_name))), so a name
    // the model already reported must not be inserted twice.
    if (usedNames.has(nameKey(fullName))) continue;
    if (looksLikePerson(fullName, null)) continue;
    usedEmails.add(email);
    usedNames.add(nameKey(fullName));

    const parts = fullName.split(/\s+/);
    people.push({
      full_name: fullName,
      first_name: parts[0],
      last_name: parts.length > 1 ? parts[parts.length - 1] : null,
      title: null,
      seniority: null,
      email,
      email_status: 'valid',
      linkedin_url: null,
      source_url: String(g.source_url || ''),
      discovery_method: 'published_page',
    });
  }
  if ((mat.github_people || []).length) {
    notes.push('observed ' + mat.github_people.length + ' address(es) in commits on ' +
      (mat.github_org ? 'github.com/' + mat.github_org : 'the company repositories') +
      ' (account found by ' + (mat.github_org_via || 'unknown') + ')');
  }

  // ---- role addresses ------------------------------------------------------
  // Recorded, never written to people: a role address has no person behind it,
  // and inventing one to satisfy a NOT NULL column would put "Careers team" in
  // the greeting of an email.
  const roleAddresses = [];
  for (const r of (Array.isArray(parsed.role_addresses) ? parsed.role_addresses : [])) {
    const email = acceptEmail(r.email, 'role address');
    if (!email) continue;
    roleAddresses.push({ email, purpose: r.purpose ? String(r.purpose).slice(0, 120) : null,
                         source: harvested.get(email) || String(r.source || '') });
  }

  // ---- pattern inference ---------------------------------------------------
  // The one place an address is produced rather than read, and it only happens
  // when this company's own site already showed one built the same way.
  //
  // Scoring across every observed pair, not just the first: two people whose
  // addresses disagree about the pattern means there is no pattern, and
  // guessing anyway is how you write to somebody who does not exist.
  const observed = people.filter((p) => p.email && p.first_name && p.last_name);
  const tally = new Map();
  for (const p of observed) {
    const local = p.email.slice(0, p.email.indexOf('@'));
    const { first, last } = nameParts(p.full_name);
    for (const pattern of PATTERNS) {
      if (pattern.build(first, last) === local) {
        tally.set(pattern.id, (tally.get(pattern.id) || 0) + 1);
        break; // first match only: the list is ordered most specific first
      }
    }
  }

  let chosen = null;
  if (tally.size > 0) {
    const ranked = [...tally.entries()].sort((a, b) => b[1] - a[1]);
    if (ranked.length === 1 || ranked[0][1] > ranked[1][1]) {
      chosen = ranked[0][0];
    } else {
      notes.push('observed addresses disagree about the pattern (' +
        ranked.map(([id, n]) => id + ' x' + n).join(', ') + '); nothing was derived');
    }
  }

  let derived = 0;
  if (chosen) {
    const builder = PATTERNS.find((p) => p.id === chosen);
    const example = observed.find((p) => {
      const { first, last } = nameParts(p.full_name);
      return builder.build(first, last) === p.email.slice(0, p.email.indexOf('@'));
    });
    for (const p of people) {
      if (p.email) continue;
      const { first, last } = nameParts(p.full_name);
      const local = builder.build(first, last);
      if (!local || local.length < 2) continue;
      const candidate = local + '@' + domain;
      if (usedEmails.has(candidate) || harvested.has(candidate)) continue;
      usedEmails.add(candidate);
      p.email = candidate;
      p.email_status = 'guessed';
      p.discovery_method = 'pattern_inferred';
      // The source is the page that proved the pattern, not a page containing
      // this address - there is none, and pretending otherwise would make
      // source_url a lie.
      p.source_url = example ? example.source_url : (mat.sources || [])[0] || null;
      derived += 1;
    }
    notes.push('address pattern "' + chosen + '" observed in ' + tally.get(chosen) +
      ' published address(es); ' + derived + ' further address(es) derived from it');
  } else if (people.some((p) => !p.email)) {
    notes.push('no address pattern could be observed on this domain, so no address was derived');
  }

  if (rawPeople.length && !people.length) {
    notes.push('every person the model returned failed verification; treated as nothing found');
  }
  if (!mat.pages_fetched) {
    notes.push('no page was readable: ' + (mat.fetch_failures || []).slice(0, 3).join(', '));
  }

  out.push({ json: {
    agent_run_id: req.agent_run_id,
    company_id: req.company_id,
    name: req.name,
    domain: req.domain,
    valid: true,
    has_people: people.length > 0,
    run_status: people.length > 0 ? 'success' : 'skipped',
    errors: [],
    error_message: null,
    notes,
    people,
    role_addresses: roleAddresses,
    dropped,
    pattern: chosen,
    derived_count: derived,
    pages_fetched: mat.pages_fetched,
    sources: mat.sources,
    raw_response: raw,
    model_output: parsed,
    usage,
  } });
}

return out;

// One search per company, to find the GitHub account by name.
//
// Guessing the account from the domain costs a call per guess out of the 60 an
// hour the unauthenticated API allows, and still misses: miro.com's account is
// "miroapp" and no guess reaches that. Search has its own separate budget of 10
// a minute, so asking it once per company is both cheaper and better.
//
// A wrong account is self-correcting further down: commit authors are kept only
// when the address is on the company's own domain, so an unrelated account
// yields nothing rather than yielding somebody else's engineers.

const GH_LINK = /github\.com\/([A-Za-z0-9][A-Za-z0-9-]{0,38})(?![A-Za-z0-9-])/gi;
const GH_RESERVED = new Set([
  'features', 'about', 'pricing', 'enterprise', 'login', 'join', 'marketplace',
  'explore', 'topics', 'collections', 'events', 'sponsors', 'readme', 'orgs',
  'apps', 'settings', 'site', 'security', 'customer-stories', 'trending',
  'search', 'new', 'notifications', 'issues', 'pulls', 'codespaces', 'sitemap',
]);

const out = [];
for (const item of $input.all()) {
  const c = item.json;
  if (String($env.ENRICH_GITHUB_ENABLED || 'true') !== 'true') continue;

  const hints = (c.github_hints || []).filter((h) => !GH_RESERVED.has(String(h).toLowerCase()));
  const label = String(c.domain || '').toLowerCase().split('.')[0].replace(/[^a-z0-9-]/g, '');

  out.push({ json: {
    company_id: c.company_id,
    domain: c.domain,
    gh_hint: hints[0] || null,
    // Searched even when there is a hint: the search is on a separate budget,
    // and the result is only used if the hint turns out not to work.
    url: 'https://api.github.com/search/users?q=' +
         encodeURIComponent(label + ' type:org') + '&per_page=5',
  } });
}

if (!out.length) {
  out.push({ json: { company_id: null, gh_noop: true,
    url: 'https://api.github.com/search/users?q=__none__+type:org' } });
}

return out;

// Choose the account that answered, and ask it for commits.
//
// The unauthenticated GitHub API allows 60 calls an hour. A company costs one
// call per candidate account plus one per repository read, so the candidate
// list is kept short and a repository with no recent pushes is not read at all.

const MAX_REPOS = Number($env.ENRICH_GITHUB_MAX_REPOS || 3);
const COMMITS_PER_REPO = Number($env.ENRICH_GITHUB_COMMITS_PER_REPO || 40);

const candidates = $('Resolve Org').all();
const responses = $input.all();

// company_id -> the first candidate account that returned repositories
const chosen = new Map();
const rate = { remaining: null };

for (let i = 0; i < responses.length; i++) {
  const cand = (candidates[i] && candidates[i].json) || {};
  if (!cand.company_id) continue;
  if (chosen.has(cand.company_id)) continue;

  const res = (responses[i] && responses[i].json) || {};
  const body = typeof res.data === 'string' ? res.data : '';
  if (!body) continue;
  let repos;
  try { repos = JSON.parse(body); } catch { continue; }
  if (!Array.isArray(repos) || !repos.length) continue;

  chosen.set(cand.company_id, { cand, repos });
}

const out = [];
for (const [companyId, { cand, repos }] of chosen) {
  const usable = repos
    .filter((r) => r && r.name && !r.archived && !r.fork)
    .slice(0, MAX_REPOS);
  for (const r of usable) {
    out.push({ json: {
      company_id: companyId,
      domain: cand.domain,
      gh_org: cand.gh_org,
      gh_via: cand.gh_via,
      repo: r.name,
      url: 'https://api.github.com/repos/' + encodeURIComponent(cand.gh_org) +
           '/' + encodeURIComponent(r.name) + '/commits?per_page=' + COMMITS_PER_REPO,
    } });
  }
}

if (!out.length) {
  out.push({ json: { company_id: null, gh_noop: true,
    url: 'https://api.github.com/repos/__none__/__none__/commits' } });
}

return out;

// Turn commit authors into observed contacts for this company.
//
// These are not model output and are not guesses: each one is a name and an
// address that appeared together in a commit on the company's own repository.
// They are handed to Validate And Verify as already-verified, which is what
// lets its existing pattern inference run at all - docs/security.md requires a
// real address observed on the domain before any address may be derived.

const MACHINE = /(^|[^a-z])(bot|ci|cd|jenkins|travis|circleci|actions|deploy|release|automation|renovate|dependabot|snyk|greenkeeper|semantic-release)([^a-z]|$)|noreply|no-reply|^git@|^root@|^admin@/i;

function fold(s) {
  return String(s || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/đ/gi, 'd').replace(/ß/g, 'ss').replace(/ø/gi, 'o')
    .replace(/ł/gi, 'l').replace(/æ/gi, 'ae')
    .toLowerCase().replace(/[^a-z]/g, '');
}

// Pull (name, address, commit url) out of a commits listing, keeping only
// addresses on the company's own domain and only humans.
function commitAuthors(commits, domain) {
  const byEmail = new Map();
  // Also keyed by name, because people.full_name carries a unique index per
  // company. One engineer committing from two addresses - a personal alias and
  // a team one - produced two rows with the same name in a single INSERT, and
  // Postgres rejects the whole statement with "ON CONFLICT DO UPDATE command
  // cannot affect row a second time". That failed the entire enrichment run for
  // the company, not just the duplicate.
  const seenNames = new Set();
  if (!Array.isArray(commits)) return [];
  const dom = String(domain || '').toLowerCase();
  for (const cm of commits) {
    const c = (cm && cm.commit) || {};
    for (const who of [c.author, c.committer]) {
      const email = String((who && who.email) || '').trim().toLowerCase();
      const name = String((who && who.name) || '').trim();
      if (!email || !name) continue;
      const host = email.slice(email.lastIndexOf('@') + 1);
      if (host !== dom && !host.endsWith('.' + dom)) continue;
      if (MACHINE.test(email) || MACHINE.test(name)) continue;
      // A single word is a handle, not a name, and the pattern check needs
      // both halves to prove anything.
      const parts = name.split(/\s+/).filter(Boolean);
      if (parts.length < 2) continue;
      if (!fold(parts[0]) || !fold(parts[parts.length - 1])) continue;
      const nameKey = name.trim().toLowerCase();
      if (!byEmail.has(email) && !seenNames.has(nameKey)) {
        seenNames.add(nameKey);
        byEmail.set(email, { full_name: name, email, source_url: cm.html_url || '' });
      }
    }
  }
  return [...byEmail.values()];
}

const MAX_PEOPLE = Number($env.ENRICH_GITHUB_MAX_PEOPLE || 12);

const companies = $('Group Material').all();
const requests = $('Pick Repos').all();
const responses = $input.all();

const byCompany = new Map();
const orgOf = new Map();

for (let i = 0; i < responses.length; i++) {
  const req = (requests[i] && requests[i].json) || {};
  if (!req.company_id) continue;
  orgOf.set(req.company_id, { org: req.gh_org, via: req.gh_via });

  const res = (responses[i] && responses[i].json) || {};
  const body = typeof res.data === 'string' ? res.data : '';
  if (!body) continue;
  let commits;
  try { commits = JSON.parse(body); } catch { continue; }

  if (!byCompany.has(req.company_id)) byCompany.set(req.company_id, new Map());
  const bucket = byCompany.get(req.company_id);
  for (const a of commitAuthors(commits, req.domain)) {
    if (!bucket.has(a.email)) bucket.set(a.email, a);
  }
}

const out = [];
for (const item of companies) {
  const c = { ...item.json };
  const found = [...(byCompany.get(c.company_id) || new Map()).values()].slice(0, MAX_PEOPLE);
  const org = orgOf.get(c.company_id) || {};

  const harvested = Array.isArray(c.harvested_emails) ? c.harvested_emails.slice() : [];
  let haystack = String(c.verification_haystack || '');

  if (found.length) {
    for (const p of found) {
      if (!harvested.some((h) => h.email === p.email)) {
        harvested.push({ email: p.email, source: p.source_url });
      }
      haystack += '\n' + p.full_name.toLowerCase() + '\n' + p.email;
    }
  }

  const { github_hints: _drop, ...rest } = c;
  out.push({ json: {
    ...rest,
    harvested_emails: harvested,
    verification_haystack: haystack,
    github_people: found,
    github_org: org.org || null,
    github_org_via: org.via || null,
    github_people_count: found.length,
  } });
}

return out;

// Settle on one account per company and ask it for repositories.
//
// A link the company published on its own pages beats a search result; the
// search is the fallback for the companies that publish no link, which was two
// of the eleven measured and includes miro.com.

const searches = $('GitHub Search').all();
const responses = $input.all();

function bestFromSearch(body, label) {
  let d;
  try { d = JSON.parse(body); } catch { return null; }
  const items = Array.isArray(d && d.items) ? d.items : [];
  if (!items.length) return null;
  const want = String(label || '').replace(/[^a-z0-9]/g, '');
  // An exact match on the login beats GitHub's own ranking; otherwise take the
  // top hit, which is what put "miroapp" first for "miro".
  const exact = items.find((u) => String(u.login || '').toLowerCase().replace(/[^a-z0-9]/g, '') === want);
  return String(((exact || items[0]) || {}).login || '') || null;
}

const out = [];
for (let i = 0; i < responses.length; i++) {
  const req = (searches[i] && searches[i].json) || {};
  if (!req.company_id) continue;

  const body = typeof (responses[i] && responses[i].json && responses[i].json.data) === 'string'
    ? responses[i].json.data : '';
  const label = String(req.domain || '').split('.')[0];
  const searched = bestFromSearch(body, label);

  const org = req.gh_hint || searched;
  if (!org) continue;

  out.push({ json: {
    company_id: req.company_id,
    domain: req.domain,
    gh_org: org,
    gh_via: req.gh_hint ? 'link' : 'search',
    gh_alt: req.gh_hint && searched && searched !== req.gh_hint ? searched : null,
    url: 'https://api.github.com/orgs/' + encodeURIComponent(org) + '/repos?sort=pushed&per_page=5',
  } });
}

if (!out.length) {
  out.push({ json: { company_id: null, gh_noop: true,
    url: 'https://api.github.com/orgs/__none__/repos' } });
}

return out;
